+  contactEmail: "ada@example.com",
+  phone: null,
+  connection: "Volunteer",
+  turnstileToken: "token",
+});
+assert.equal(
+  parseSignupInput({ ...validInput, contactEmail: "nope" }).errors?.contactEmail,
